package java.util.concurrent.atomic; public class AtomicReferenceArray<T>{private final Object[] a;public AtomicReferenceArray(int n){a=new Object[n];}public int length(){return a.length;}public T get(int i){return (T)a[i];}public void set(int i,T v){a[i]=v;}public void lazySet(int i,T v){set(i,v);}public T getAndSet(int i,T v){T old=get(i);set(i,v);return old;}public boolean compareAndSet(int i,T old,T v){if(a[i]!=old)return false;a[i]=v;return true;}}